class Solution:
    def maxLen(self, n: int, edges: List[List[int]], label: str) -> int:
        adj = [0] * n
        for u, v in edges:
            adj[u] |= 1 << v
            adj[v] |= 1 << u
        seen = set()
        best = 1
        for i in range(n):
            seen.add((1 << i, i, i))
        for u, v in edges:
            if label[u] == label[v]:
                st = ((1 << u) | (1 << v), u, v)
                if st not in seen:
                    seen.add(st); best = 2
        frontier = list(seen)
        while frontier:
            nxt = []
            for mask, i, j in frontier:
                if bin(mask).count('1') > best: best = mask.bit_count()
                for k in range(n):
                    if mask >> k & 1: continue
                    if (adj[i] >> k & 1) and label[k] == label[j]:
                        st = (mask | 1 << k, k, j)
                        if st not in seen: seen.add(st); nxt.append(st)
                    if (adj[j] >> k & 1) and label[k] == label[i]:
                        st = (mask | 1 << k, i, k)
                        if st not in seen: seen.add(st); nxt.append(st)
            frontier = nxt
        return best

