class Solution {
public:
    int maxLen(int n, vector<vector<int>>& edges, string label) {
        vector<int> adj(n, 0);
        for (auto& e : edges) { adj[e[0]] |= 1 << e[1]; adj[e[1]] |= 1 << e[0]; }
        set<tuple<int,int,int>> seen;
        int best = 1;
        vector<tuple<int,int,int>> frontier;
        for (int i = 0; i < n; i++) { seen.insert({1 << i, i, i}); frontier.push_back({1 << i, i, i}); }
        for (auto& e : edges) if (label[e[0]] == label[e[1]]) {
            auto st = make_tuple((1 << e[0]) | (1 << e[1]), e[0], e[1]);
            if (seen.insert(st).second) { frontier.push_back(st); best = 2; }
        }
        while (!frontier.empty()) {
            vector<tuple<int,int,int>> nxt;
            for (auto& [mask, i, j] : frontier) {
                best = max(best, __builtin_popcount(mask));
                for (int k = 0; k < n; k++) {
                    if (mask >> k & 1) continue;
                    if ((adj[i] >> k & 1) && label[k] == label[j]) {
                        auto st = make_tuple(mask | 1 << k, k, j);
                        if (seen.insert(st).second) nxt.push_back(st);
                    }
                    if ((adj[j] >> k & 1) && label[k] == label[i]) {
                        auto st = make_tuple(mask | 1 << k, i, k);
                        if (seen.insert(st).second) nxt.push_back(st);
                    }
                }
            }
            frontier = move(nxt);
        }
        return best;
    }
};

