class Solution {
    public int maxLen(int n, int[][] edges, String label) {
        int[] adj = new int[n];
        for (int[] e : edges) { adj[e[0]] |= 1 << e[1]; adj[e[1]] |= 1 << e[0]; }
        Set<Long> seen = new HashSet<>();
        List<int[]> frontier = new ArrayList<>();
        int best = 1;
        for (int i = 0; i < n; i++) { seen.add(key(1 << i, i, i)); frontier.add(new int[]{1 << i, i, i}); }
        for (int[] e : edges) if (label.charAt(e[0]) == label.charAt(e[1])) {
            long k = key((1 << e[0]) | (1 << e[1]), e[0], e[1]);
            if (seen.add(k)) { frontier.add(new int[]{(1 << e[0]) | (1 << e[1]), e[0], e[1]}); best = 2; }
        }
        while (!frontier.isEmpty()) {
            List<int[]> nxt = new ArrayList<>();
            for (int[] s : frontier) {
                int mask = s[0], i = s[1], j = s[2];
                best = Math.max(best, Integer.bitCount(mask));
                for (int k = 0; k < n; k++) {
                    if ((mask >> k & 1) != 0) continue;
                    if ((adj[i] >> k & 1) != 0 && label.charAt(k) == label.charAt(j)) {
                        long kk = key(mask | 1 << k, k, j);
                        if (seen.add(kk)) nxt.add(new int[]{mask | 1 << k, k, j});
                    }
                    if ((adj[j] >> k & 1) != 0 && label.charAt(k) == label.charAt(i)) {
                        long kk = key(mask | 1 << k, i, k);
                        if (seen.add(kk)) nxt.add(new int[]{mask | 1 << k, i, k});
                    }
                }
            }
            frontier = nxt;
        }
        return best;
    }
    private long key(int mask, int i, int j) { return ((long) mask << 8) | (i << 4) | j; }
}

