var maxLen = function(n, edges, label) {
    const adj = Array(n).fill(0);
    for (const [u, v] of edges) { adj[u] |= 1 << v; adj[v] |= 1 << u; }
    const seen = new Set();
    let frontier = [], best = 1;
    for (let i = 0; i < n; i++) { const s = (1 << i) + ',' + i + ',' + i; seen.add(s); frontier.push([1 << i, i, i]); }
    for (const [u, v] of edges) if (label[u] === label[v]) {
        const s = ((1 << u) | (1 << v)) + ',' + u + ',' + v;
        if (!seen.has(s)) { seen.add(s); frontier.push([(1 << u) | (1 << v), u, v]); best = 2; }
    }
    while (frontier.length) {
        const nxt = [];
        for (const [mask, i, j] of frontier) {
            best = Math.max(best, mask.toString(2).split('1').length - 1);
            for (let k = 0; k < n; k++) {
                if (mask >> k & 1) continue;
                if ((adj[i] >> k & 1) && label[k] === label[j]) {
                    const s = (mask | 1 << k) + ',' + k + ',' + j;
                    if (!seen.has(s)) { seen.add(s); nxt.push([mask | 1 << k, k, j]); }
                }
                if ((adj[j] >> k & 1) && label[k] === label[i]) {
                    const s = (mask | 1 << k) + ',' + i + ',' + k;
                    if (!seen.has(s)) { seen.add(s); nxt.push([mask | 1 << k, i, k]); }
                }
            }
        }
        frontier = nxt;
    }
    return best;
};
